export const storefrontCopy = Object.fromEntries(['en', 'id', 'ms'].map((language, index) => [
  language,
  Object.fromEntries(Object.entries(messages).map(([key, translations]) => [key, translations[index]])),
]))

export function formatCopy(template, values) {
  return template.replace(/\{(\w+)\}/g, (_, key) => String(values[key] ?? ''))
}
